// controller/user.ts
var user_default = {
  getAll: (req, res) => {
    const page = Math.max(1, parseInt(req.query.page ?? "1") || 1);
    const limit = Math.max(1, parseInt(req.query.limit ?? "6") || 6);
    const total = users_default.length;
    const totalPage = Math.ceil(total / limit);
    const start = limit * (page - 1);
    const data = users_default.slice(start, start + limit);
    res.json({ page, limit, total, total_page: totalPage, data });
  },
  getById: (req, res) => {
    const { id } = req.params;
    const user = users_default.find((u) => u.id === Number(id));
    if (user === undefined) {
      return res.status(404).json({ message: "User not found" });
    }
    res.json({ data: user });
  },
  create: (req, res) => {
    const { name, email, avatar } = req.body;
    if (!name || !email) {
      return res.status(400).json({ message: "Name and email are required" });
    }
    const nextId = users_default.length > 0 ? Math.max(...users_default.map((u) => u.id)) + 1 : 1;
    const newUser = {
      id: nextId,
      name,
      email,
      avatar: avatar ?? `https://picsum.photos/id/${nextId}/200/200`
    };
    res.status(201).json({ data: newUser });
  },
  update: (req, res) => {
    const { id } = req.params;
    const index = users_default.findIndex((u) => u.id === Number(id));
    if (index === -1) {
      return res.status(404).json({ message: "User not found" });
    }
    const { name, email, avatar } = req.body;
    const updatedUser = {
      ...users_default[index],
      ...name && { name },
      ...email && { email },
      ...avatar && { avatar }
    };
    res.json({ data: updatedUser });
  },
  destroy: (req, res) => {
    const { id } = req.params;
    const index = users_default.findIndex((u) => u.id === Number(id));
    if (index === -1) {
      return res.status(404).json({ message: "User not found" });
    }
    res.json({ message: "User deleted successfully" });
  }
};

